def metrics(e, m):
    z = e[m]
    return np.round([np.sqrt(np.mean(z[:, :-1] ** 2)), np.sqrt(np.mean(z[:, -1] ** 2)), np.max(np.sqrt(np.mean(z[:, :-1] ** 2, axis=0)))], 6).tolist()

def _checks(checks, lab):
    labs, x, y = (np.asarray(checks[k]) for k in ('lab_id', 'cmd_stress', 'true_stress'))
    m = (labs == lab) & np.isfinite(x) & np.isfinite(y)
    return (x[m], y[m])

def _with_prior(x, y, fits, prior):
    gain, bias = prior
    if not len(x):
        return prior
    offsets = y - gain * x - bias
    center = np.median(offsets)
    agreeing = np.abs(offsets - center) <= 0.004
    if agreeing.sum() > len(x) // 2 and (len(x) > 1 or abs(center) < 0.1):
        bias += np.median(offsets[agreeing])
    else:
        i = np.argmin(np.abs(offsets))
        if abs(offsets[i]) < 0.1:
            bias += offsets[i]
    for fit, count, span in fits:
        if count >= 3 and span >= 0.4 and (abs(fit[0] - gain) <= 0.01) and (abs(fit[1] - bias) <= 0.01):
            return fit
    return (gain, bias)

def _crossing(gap, amp, drift, taus, horizon):
    """First upward threshold hit, including hits between the sampled times."""
    from scipy.optimize import brentq
    if gap <= 0:
        return 0.0

    def level(t):
        return drift * t - np.dot(amp, np.expm1(-t / taus)) - gap
    rates = amp / taus

    def speed(t):
        return drift + np.dot(rates, np.exp(-t / taus))
    pieces = [0.0, horizon]
    a, b = rates / taus
    denominator = 1.0 / taus[0] - 1.0 / taus[1]
    if np.sign(a) * np.sign(b) == -1 and denominator != 0.0:
        inflection = (np.log(abs(a)) - np.log(abs(b))) / denominator
        if 0.0 < inflection < horizon:
            pieces.insert(1, inflection)
    knots = [0.0]
    for lo, hi in zip(pieces[:-1], pieces[1:]):
        slo, shi = (speed(lo), speed(hi))
        if slo * shi < 0.0:
            knots.append(brentq(speed, lo, hi))
        if shi == 0.0 or hi == horizon:
            knots.append(hi)
    for lo, hi in zip(knots[:-1], knots[1:]):
        if level(hi) >= 0.0:
            return brentq(level, lo, hi)
    return horizon
